
*{box-sizing:border-box}body{margin:0;background:var(--tint);color:var(--ink);font-family:Georgia,"Times New Roman",serif;font-size:15px;line-height:1.7;height:100dvh;overflow:hidden}button,input,select,textarea{font:inherit}button,a,input,select,textarea{-webkit-tap-highlight-color:transparent}a{color:inherit}button{cursor:pointer}button:disabled{opacity:.55;cursor:not-allowed}:focus-visible{outline:3px solid var(--gold);outline-offset:4px}[hidden]{display:none!important}.desktop-backdrop{position:fixed;inset:0;overflow:hidden}.desktop-backdrop img{width:100%;height:100%;object-fit:cover;filter:blur(9px);transform:scale(1.05)}.desktop-backdrop:after{content:"";position:absolute;inset:0;background:var(--tint);opacity:var(--veil)}
.phone-frame{position:relative;width:430px;max-width:calc(100% - 40px);height:calc(100dvh - 36px);margin:18px auto;border:10px solid #c5b3a0;box-shadow:0 0 0 3px #796857,0 0 0 5px #d9cbb6,0 30px 100px #0005;border-radius:48px;background:var(--paper);overflow:hidden}.phone-notch{position:absolute;top:11px;left:50%;transform:translateX(-50%);width:86px;height:20px;background:#28231e;border-radius:18px;z-index:20;pointer-events:none}.invitation-scroll{height:100%;overflow-y:auto;overflow-x:hidden;scroll-behavior:smooth;scrollbar-width:none}.invitation-scroll::-webkit-scrollbar{display:none}.page-section{position:relative;padding:70px 30px 110px;text-align:center;background:var(--paper);scroll-margin-top:0;overflow-wrap:anywhere}.ornamental{background:radial-gradient(ellipse at 0 0,color-mix(in srgb,var(--gold) 18%,transparent),transparent 55%),radial-gradient(ellipse at 100% 100%,color-mix(in srgb,var(--accent) 8%,transparent),transparent 50%),var(--paper);border-bottom:1px solid var(--line)}.ornamental:before,.ornamental:after{content:"";position:absolute;left:12px;right:12px;top:18px;bottom:18px;border:1px solid var(--line);border-radius:140px 140px 5px 5px;pointer-events:none}.ornamental:after{inset:24px 18px;border-radius:135px 135px 3px 3px;opacity:.5}.page-section>*{position:relative;z-index:1}.cover{min-height:100%;padding-top:65px}.eyebrow{display:block;font:10px/1.8 Arial,sans-serif;letter-spacing:.24em;text-transform:uppercase;color:var(--accent);margin-bottom:22px}h1,h2,h3{font-weight:400;color:var(--accent);line-height:1.2;overflow-wrap:anywhere}h1{font-size:34px;margin:26px 0 18px}h2{font-size:36px;margin:12px 0 28px}h3{font-size:27px;margin:22px 0}p{margin:14px 0}.arch-photo{display:block;width:100%;max-width:280px;aspect-ratio:3/4;object-fit:cover;border-radius:150px 150px 3px 3px;border:1px solid var(--gold);padding:5px;margin:25px auto;background:color-mix(in srgb,var(--paper) 80%,transparent)}.cover-photo{max-width:220px;max-height:290px}.date-label{font:11px Arial,sans-serif;letter-spacing:.25em;margin:25px 0}.guest-salutation{margin:30px 0}.guest-salutation strong{font-size:18px}.prose{white-space:pre-line;line-height:1.95}.quote,.cover-closing{font-style:italic}.cover-closing{opacity:.75;font-size:15px;margin-top:22px}.button{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:13px 20px;border:1px solid var(--gold);border-radius:5px;background:transparent;color:var(--accent);text-decoration:none;font:12px/1.5 Arial,sans-serif;min-height:44px}.button.solid{background:var(--accent);color:var(--paper)}.full-photo{min-height:calc(100dvh - 60px);display:flex;align-items:flex-end;justify-content:center;background:var(--accent);color:#fff}.background-media{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:0}.full-photo:after{content:"";position:absolute;inset:0;background:linear-gradient(transparent,#0009);pointer-events:none}.photo-caption{z-index:1}.photo-caption h2,.photo-caption h3,.photo-caption .eyebrow{color:#fff}.photo-caption h2{font-size:43px}.photo-caption small{display:block;margin-top:45px;font:10px Arial,sans-serif;letter-spacing:.2em}.ampersand{display:block;font-style:italic;font-size:.65em;margin:10px}.ornament{display:block;color:var(--gold);font-size:38px;margin:15px}.rule{display:block;width:50px;height:1px;background:var(--gold);margin:25px auto}.countdown{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin:30px 0 14px}.countdown>div{border:1px solid var(--line);border-radius:40px 40px 4px 4px;padding:16px 3px 12px;background:color-mix(in srgb,var(--paper) 70%,transparent)}.countdown strong{display:block;font-size:28px;font-weight:400;line-height:1.3;color:var(--accent)}.countdown small{font:9px Arial,sans-serif}.muted{opacity:.7;font-size:13px}.event-card{border:1px solid var(--line);background:color-mix(in srgb,var(--paper) 88%,white);border-radius:130px 130px 8px 8px;padding:35px 20px;margin:42px 0 0}.story-card{position:relative;border:1px solid var(--line);border-radius:12px;padding:18px;text-align:left;background:color-mix(in srgb,var(--paper) 80%,white);margin:24px 0}.story-card img{width:100%;aspect-ratio:4/3;object-fit:cover;border-radius:8px}.story-card h3{font-size:23px}.gallery-track{display:flex;gap:12px;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none}.gallery-track>a{flex:0 0 94%;scroll-snap-align:center}.gallery-track .arch-photo{max-width:100%;margin:10px 0}.gallery-controls{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:16px;font:11px Arial,sans-serif}.gallery-controls button{width:42px;height:42px;border-radius:50%;border:1px solid var(--gold);background:transparent;color:var(--accent)}.guest-form{padding:22px 18px;border:1px solid var(--line);border-radius:10px;text-align:left;background:color-mix(in srgb,var(--paper) 80%,white);margin-top:28px}.guest-form label{display:block;font:11px Arial,sans-serif;margin:17px 0 8px;color:var(--accent)}.guest-form input:not([type=hidden]),.guest-form textarea,.guest-form select{width:100%;padding:12px;border:1px solid var(--line);border-radius:5px;background:var(--paper);color:var(--ink);min-width:0}.guest-form small{display:block;font-size:11px;margin:18px 0}.guest-form .button{width:100%}.honey{position:absolute;left:-10000px}.feedback{padding:16px;border:1px solid var(--gold);font-size:13px;line-height:1.6;border-radius:8px}.wishes{text-align:left}.wish{display:flex;gap:12px;padding:22px 0;border-bottom:1px solid var(--line)}.wish>div{min-width:0;flex:1}.avatar{flex:0 0 32px;height:32px;border-radius:50%;display:grid;place-items:center;background:color-mix(in srgb,var(--accent) 12%,var(--paper));font:12px Arial,sans-serif}.wish strong{font-weight:400;color:var(--accent)}.wish time{display:block;font:10px Arial,sans-serif;opacity:.6;margin-top:6px}.wish p{white-space:pre-line;overflow-wrap:anywhere;font-size:14px;line-height:1.9}.pagination{display:flex;justify-content:center;align-items:center;flex-wrap:wrap;gap:12px;margin:25px 0;font:11px Arial,sans-serif}.pagination .button{padding:10px}.gift-card{padding:25px 18px;border:1px solid var(--line);border-radius:12px;margin:24px 0}.gift-card small{font:10px Arial,sans-serif;color:var(--accent)}.account-number{font-size:23px;letter-spacing:.06em}.gift-card .button{width:100%;margin-top:12px}footer{text-align:center;background:var(--paper);padding:30px 20px 115px;font:10px Arial,sans-serif;letter-spacing:.14em}.bottom-controls{position:absolute;bottom:14px;left:12px;right:12px;display:flex;align-items:center;gap:7px;z-index:10}.bottom-menu{display:flex;flex:1;min-width:0;overflow-x:auto;background:color-mix(in srgb,var(--paper) 96%,white);border:1px solid var(--line);border-radius:34px;padding:9px 8px;scrollbar-width:none;box-shadow:0 5px 20px #0001}.bottom-menu a{flex:0 0 53px;text-align:center;text-decoration:none;font:9px Arial,sans-serif;color:var(--accent);opacity:.7;padding:3px}.bottom-menu a span{display:block;font:20px Georgia;margin-bottom:4px}.bottom-menu a[aria-current]{opacity:1;background:color-mix(in srgb,var(--accent) 10%,transparent);border-radius:20px}#music-toggle{flex:0 0 43px;height:43px;border:1px solid var(--line);border-radius:50%;background:var(--paper);color:var(--accent);font-size:23px}#music-toggle[aria-pressed=true]{box-shadow:0 0 0 3px color-mix(in srgb,var(--accent) 25%,transparent)}.preview{position:relative;z-index:5;padding:10px 18px;background:var(--accent);color:var(--paper);font:10px/1.5 Arial,sans-serif;text-align:center}.awaiting-open main>:not(#cover){display:none}.awaiting-open .bottom-controls{display:none!important}.awaiting-open #cover{min-height:calc(100dvh - 60px)}
@media(max-width:600px){.phone-frame{width:100%;max-width:none;height:100dvh;margin:0;border:0;border-radius:0;box-shadow:none}.phone-notch,.desktop-backdrop{display:none}.page-section{padding-left:30px;padding-right:30px}.full-photo{min-height:100dvh}.awaiting-open #cover{min-height:100dvh}.bottom-controls{bottom:calc(12px + env(safe-area-inset-bottom));left:12px;right:12px}}
@media(prefers-reduced-motion:reduce){.invitation-scroll{scroll-behavior:auto}}
